 export const DEFAULT_BASE_URL = "https://metrics.ops.internal/v1";

@@ -9,11 +10,36 @@
   readonly fetchImpl: typeof fetch;

   constructor(options: MetricsClientOptions = {}) {
-    throw new Error("not implemented");
+    let baseUrl = options.baseUrl ?? DEFAULT_BASE_URL;
+    if (baseUrl.endsWith("/")) baseUrl = baseUrl.slice(0, -1);
+    this.baseUrl = baseUrl;
+    this.fetchImpl = options.fetchImpl ?? fetch;
   }

-  /** The samples of a metric over the last `windowSeconds` seconds. */
   async getSeries(metric: string, windowSeconds: number): Promise<Sample[]> {
-    throw new Error("not implemented");
+    if (!/^[a-z][a-z0-9_]{0,62}$/.test(metric)) throw new RangeError();
+    if (!Number.isInteger(windowSeconds) || windowSeconds < 60 || windowSeconds > 86400) throw new RangeError();
+
+    const url = `${this.baseUrl}/series?metric=${metric}&window=${windowSeconds}`;
+
+    let response: Response;
+    try {
+      response = await this.fetchImpl(url);
+    } catch (e) {
+      throw new MetricsError(`metrics service unavailable: ${(e as Error).message}`);
+    }
+
+    if (!response.ok) {
+      throw new MetricsError(`metrics service answered HTTP ${response.status}`);
+    }
+
+    let body: unknown;
+    try {
+      body = await response.json();
+    } catch {
+      throw new MetricsError();
+    }
